    "7681": "无法获取浏览器窗口",
    "7683": "点击打开AI引擎配置",
    "7684": "云端共享原理说明",
    "7685": "始终将隐私保护作为核心设计原则，坚持",
    "7686": "数据本地优先",
    "7687": "，切实保障用户隐私安全，其核心技术原理与行业常见的哈希（Hash）机制逻辑一致。",
    "7688": "简单来说",
    "7689": "，系统会通过加密算法为每个文件生成唯一的特征标识（长度 16-128 字符），相当于文件的专属 ID。",
    "7690": "生成这一 ID 的",
    "7691": "唯一前提",
    "7692": "，是用户本地持有该文件并完成算法计算，应用不会向任何第三方泄露该文件 ID。仅凭借此 ID，才可向服务器请求对应 ID 的分析数据，无其他获取途径。",
    "7693": "即便在",
    "7694": "极端假设下",
    "7695": "（服务器被突破），第三方仅能获取文件分析数据与对应 ID，且不同平台的 ID 算法完全独立，与百度网盘等平台的文件 ID 无任何关联，无法跨平台匹配原文件。",
    "7696": "同时，",
    "7697": "服务器仅存储分析类数据",
    "7698": "：包括智能文件名、标签、内容摘要、评分及理由、元数据等，也就是大家在右侧属性面板可见的内容，绝不会上传、存储文件本体。",
